import zipfile,json,collections,re
z=zipfile.ZipFile(r'G:/ck-web26/client-26.2.jar')
n=[p for p in z.namelist() if p.startswith('assets/minecraft/blockstates/') and p.endswith('.json')]
propvals=collections.defaultdict(set)
total_variants=0
referenced_models=set()
for p in n:
    d=json.loads(z.read(p))
    if 'multipart' in d:
        total_variants+=len(d['multipart'])
        for part in d['multipart']:
            if isinstance(part.get('apply'),dict) and 'model' in part['apply']: referenced_models.add(part['apply']['model'])
            for w in ([part['when']] if isinstance(part.get('when'),dict) else part.get('when',[]) or []):
                for k,v in w.items():
                    if k=='OR':
                        for vv in v:
                            for kk,vvv in (vv.items() if isinstance(vv,dict) else []): propvals[kk].add(str(vvv))
                    else: propvals[k].add(str(v))
    else:
        for key,val in d.items():
            total_variants+=1
            for seg in key.split(';'):
                if '=' in seg:
                    k,v=seg.split('=',1); propvals[k].add(v)
            vals=val if isinstance(val,list) else [val]
            for v in vals:
                if isinstance(v,dict) and 'model' in v: referenced_models.add(v['model'])
print('total render-state variants/parts across 1198 blockstates:',total_variants)
print('distinct model refs used by blockstates:',len(referenced_models))
print('distinct blockstate PROPERTIES:',len(propvals))
for k,v in sorted(propvals.items(), key=lambda x:-len(x[1]))[:40]:
    print(f'  {len(v):3d} vals  {k:22s} e.g. {sorted(v)[:6]}')
"

