import zipfile,json,collections
z=zipfile.ZipFile(r'G:/ck-web26/client-26.2.jar')
it=[p for p in z.namelist() if p.startswith('assets/minecraft/items/') and p.endswith('.json')]
types=collections.Counter(); props=collections.Counter(); selectors=collections.Counter(); tint=collections.Counter()
def walk(m):
    if isinstance(m,dict):
        types[m.get('type','?')]+=1
        sel=m.get('selection_mode') or m.get('property')
        if isinstance(sel,str): props[sel]+=1
        if isinstance(sel,dict): selectors[sel.get('type','?')]+=1
        if m.get('type')=='minecraft:composite':
            for s in m.get('models',[]): walk(s)
        for key in ('fallback','model','base'):
            if isinstance(m.get(key),dict): walk(m[key])
        for c in (m.get('cases') or []):
            if isinstance(c,dict) and isinstance(c.get('model'),dict): walk(c['model'])
        for td in (m.get('tints') or []): tint[td.get('type','?')]+=1
for p in it:
    d=json.loads(z.read(p))
    walk(d.get('model'))
print('ITEM DEFINITION model selector types (%d defs):'%len(it))
for k,v in types.most_common(): print(f'  {v:5d}  {k}')
print()
print('item-definition selection PROPERTIES:',len(props))
for k,v in props.most_common(22): print(f'  {v:5d}  {k}')
print()
print('property selector types:',dict(selectors))
print('tint sources:',dict(tint))
"

